begin;drop policy fpg_jobs_read on public.fpg_refresh_jobs;create policy fpg_jobs_read on public.fpg_refresh_jobs for select to authenticated using((select fpg_private.v74_owner()));drop policy fpg_jobs_queue on public.fpg_refresh_jobs;create policy fpg_jobs_queue on public.fpg_refresh_jobs for insert to authenticated with check((select fpg_private.v74_owner()) and created_by=(select auth.uid()) and status='pending' and claimed_by is null and started_at is null and finished_at is null);drop policy fpg_jobs_finish on public.fpg_refresh_jobs;create policy fpg_jobs_finish on public.fpg_refresh_jobs for update to authenticated using((select fpg_private.v74_owner()) and claimed_by=(select auth.uid()) and status='running') with check((select fpg_private.v74_owner()) and claimed_by=(select auth.uid()) and status in ('complete','failed'));do $$declare d text;begin select pg_get_functiondef('fpg_private.claim_job()'::regprocedure) into d;d:=replace(d,'if auth.uid() is null or coalesce(fpg_private.role(),'''') not in (''admin'',''controller'',''accountant'') then raise exception ''Finance worker access required'';end if;','if not coalesce(fpg_private.v74_owner(),false) then raise exception ''Python controls are restricted to netsgcwork@gmail.com'';end if;');execute d;end $$;commit;